<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\ThemeAssetTypeVO;

trait ThemeAssetTypeAttributeHolder
{
    protected ThemeAssetTypeVO|string|null $type = null;
    protected bool $typeAssigned = false;

    public function getTypeOrCurrent(ThemeAssetTypeVO $type): ThemeAssetTypeVO
    {
        if ($this->typeAssigned) {
            \assert(null !== $this->type);
            return ThemeAssetTypeVO::from($this->type);
        } else {
            return $type;
        }
    }
    public function typeTryBuildInitial(ConstraintFailList $error): ?ThemeAssetTypeVO
    {
        return  ThemeAssetTypeVO::tryFrom($this->typeAssigned ? $this->type : null, $error);
    }
    public function type(ThemeAssetTypeVO|string $type): static
    {
        $this->type = $type;
        $this->typeAssigned = true;
        return $this;
    }
    public function getType(): ?string
    {
        return $this->type instanceof ThemeAssetTypeVO ? $this->type->value() : $this->type;
    }
    public function isTypeAssigned(): bool
    {
        return $this->typeAssigned;
    }
    public function writeTypeTo(mixed $att): void
    {
        if ($this->typeAssigned) {
            \assert(null !== $this->type);
            $att->type($this->type);
        }
    }
    public function readTypeFrom(mixed $att): void
    {
        if ($att->isTypeAssigned()) {
            $type = $att->getType();
            \assert(null !== $type);
            $this->type($type);
        }
    }
    public function unsetType(): static
    {
        $this->typeAssigned = false;
        return $this;
    }
    protected function withDefaultType(): void
    {
    }
    protected function withAssertedTypeRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->typeAssigned = $this->typeAssigned) {
            $value->type = ThemeAssetTypeVO::tryFrom($this->type, $errorsList);
        }
    }
}
